local BND_IS_CONTROLLER_TYPE_GAMEPAD = "bnd_is_controller_type_gamepad"local BND_IS_CONTROLLER_TYPE_KEYBOARD_ONLY = "bnd_is_controller_type_keyboard_only"local BND_IS_CONTROLLER_TYPE_KEYBOARD_AND_MOUSE = "bnd_is_controller_type_keyboard_and_mouse"local BND_IS_CONTROLLER_CONFIGURATION_CLASSIC = "bnd_is_controller_configuration_classic"local BND_IS_CONTROLLER_CONFIGURATION_ALTERNATE = "bnd_is_controller_configuration_alternate"local BND_IS_CONTROLLER_CONFIGURATION_TWO_BUTTONS = "bnd_is_controller_configuration_two_buttons"local GameSettingsModel = {}GameSettingsModel.CONTROLLER_ID_GAMEPAD = 0GameSettingsModel.CONTROLLER_ID_KEYBOARD = 4GameSettingsModel.SUB_CONTROLLER_ID_KEYBOARD_AND_MOUSE = 0GameSettingsModel.SUB_CONTROLLER_ID_KEYBOARD_ONLY = 1GameSettingsModel.CONTROLLER_TYPE_UNKNOWN = -1GameSettingsModel.CONTROLLER_TYPE_KEYBOARD_AND_MOUSE = 0GameSettingsModel.CONTROLLER_TYPE_KEYBOARD_ONLY = 1GameSettingsModel.CONTROLLER_TYPE_GAMEPAD = 2GameSettingsModel.CONTROLLER_CONFIGURATION_UNKNOWN = -1GameSettingsModel.CONTROLLER_CONFIGURATION_CLASSIC = 0GameSettingsModel.CONTROLLER_CONFIGURATION_ALTERNATE = 1GameSettingsModel.CONTROLLER_CONFIGURATION_TWO_BUTTONS = 2GameSettingsModel.CONTROLLER_CONFIGURATION_PC_CONTROL = 2function GameSettingsModel:new(init)  local o = init or {}  setmetatable(o, self)  self.__index = self  o.services = {    GameStateService = o.api("GameStateService"),    FifaCustomizationService = o.api("FifaCustomizationService")  }  o.im.Subscribe(BND_IS_CONTROLLER_TYPE_GAMEPAD, function()    o:_publishControllerTypeFlag(BND_IS_CONTROLLER_TYPE_GAMEPAD)  end  )  o.im.Subscribe(BND_IS_CONTROLLER_TYPE_KEYBOARD_ONLY, function()    o:_publishControllerTypeFlag(BND_IS_CONTROLLER_TYPE_KEYBOARD_ONLY)  end  )  o.im.Subscribe(BND_IS_CONTROLLER_TYPE_KEYBOARD_AND_MOUSE, function()    o:_publishControllerTypeFlag(BND_IS_CONTROLLER_TYPE_KEYBOARD_AND_MOUSE)  end  )  o.im.Subscribe(BND_IS_CONTROLLER_CONFIGURATION_CLASSIC, function()    o:_publishControllerConfigurationFlag(BND_IS_CONTROLLER_CONFIGURATION_CLASSIC)  end  )  o.im.Subscribe(BND_IS_CONTROLLER_CONFIGURATION_ALTERNATE, function()    o:_publishControllerConfigurationFlag(BND_IS_CONTROLLER_CONFIGURATION_ALTERNATE)  end  )  o.im.Subscribe(BND_IS_CONTROLLER_CONFIGURATION_TWO_BUTTONS, function()    o:_publishControllerConfigurationFlag(BND_IS_CONTROLLER_CONFIGURATION_TWO_BUTTONS)  end  )  return oendfunction GameSettingsModel:getControllerType()  if self.services.GameStateService.GetControllerSide(GameSettingsModel.CONTROLLER_ID_GAMEPAD) == 0 then    return GameSettingsModel.CONTROLLER_TYPE_GAMEPAD  elseif self.services.GameStateService.GetControllerSide(GameSettingsModel.CONTROLLER_ID_KEYBOARD) == 0 then    local subtype = self.services.GameStateService.GetSubTypePreferedControllerId(GameSettingsModel.CONTROLLER_ID_KEYBOARD)    if subtype == GameSettingsModel.SUB_CONTROLLER_ID_KEYBOARD_AND_MOUSE then      return GameSettingsModel.CONTROLLER_TYPE_KEYBOARD_AND_MOUSE    elseif subtype == GameSettingsModel.SUB_CONTROLLER_ID_KEYBOARD_ONLY then      return GameSettingsModel.CONTROLLER_TYPE_KEYBOARD_ONLY    else      return GameSettingsModel.CONTROLLER_TYPE_UNKNOWN    end  else    return GameSettingsModel.CONTROLLER_TYPE_UNKNOWN  endendfunction GameSettingsModel:setControllerType(controllerType)  assert(controllerType ~= nil, "Controller type is nil.")  if controllerType == GameSettingsModel.CONTROLLER_TYPE_KEYBOARD_AND_MOUSE then    self.services.GameStateService.SetHomeController(GameSettingsModel.CONTROLLER_ID_KEYBOARD, GameSettingsModel.SUB_CONTROLLER_ID_KEYBOARD_AND_MOUSE, false)  elseif controllerType == GameSettingsModel.CONTROLLER_TYPE_KEYBOARD_ONLY then    self.services.GameStateService.SetHomeController(GameSettingsModel.CONTROLLER_ID_KEYBOARD, GameSettingsModel.SUB_CONTROLLER_ID_KEYBOARD_ONLY, false)  elseif controllerType == GameSettingsModel.CONTROLLER_TYPE_GAMEPAD then    self.services.GameStateService.SetHomeController(GameSettingsModel.CONTROLLER_ID_GAMEPAD, 0, false)  else    error("Unknown controller type:", tostring(controllerType))  endendfunction GameSettingsModel:getControllerConfiguration(controllerType)  if controllerType == nil then    controllerType = self:getControllerType()  end  if controllerType == GameSettingsModel.CONTROLLER_TYPE_GAMEPAD then    return self.services.FifaCustomizationService.GetControllerConfiguration(GameSettingsModel.CONTROLLER_ID_GAMEPAD)  elseif controllerType == GameSettingsModel.CONTROLLER_TYPE_KEYBOARD_ONLY then    return self.services.FifaCustomizationService.GetControllerConfiguration(GameSettingsModel.CONTROLLER_ID_KEYBOARD)  else    return GameSettingsModel.CONTROLLER_CONFIGURATION_UNKNOWN  endendfunction GameSettingsModel:setControllerConfiguration(controllerType, controllerConfiguration)  assert(controllerConfiguration ~= nil, "Controller configuration is nil.")  if controllerType == nil then    controllerType = self:getControllerType()  end  if controllerType == GameSettingsModel.CONTROLLER_TYPE_KEYBOARD_AND_MOUSE then    error("There are no controller configurations for keyboard and mouse.")    return  elseif controllerType == GameSettingsModel.CONTROLLER_TYPE_KEYBOARD_ONLY then    self.services.FifaCustomizationService.SetKeyboardConfiguration(GameSettingsModel.CONTROLLER_ID_KEYBOARD, controllerConfiguration)  elseif controllerType == GameSettingsModel.CONTROLLER_TYPE_GAMEPAD then    self.services.FifaCustomizationService.SetKeyboardConfiguration(GameSettingsModel.CONTROLLER_ID_GAMEPAD, controllerConfiguration)  else    error("Unknown controller type:", tostring(controllerType))  endendfunction GameSettingsModel:_publishControllerTypeFlag(bindingName)  if bindingName == nil then    self:_publishControllerTypeFlag(BND_IS_CONTROLLER_TYPE_GAMEPAD)    self:_publishControllerTypeFlag(BND_IS_CONTROLLER_TYPE_KEYBOARD_ONLY)    self:_publishControllerTypeFlag(BND_IS_CONTROLLER_TYPE_KEYBOARD_AND_MOUSE)  elseif bindingName == BND_IS_CONTROLLER_TYPE_GAMEPAD then    self.im.Publish(BND_IS_CONTROLLER_TYPE_GAMEPAD, self:getControllerType() == GameSettingsModel.CONTROLLER_TYPE_GAMEPAD)  elseif bindingName == BND_IS_CONTROLLER_TYPE_KEYBOARD_ONLY then    self.im.Publish(BND_IS_CONTROLLER_TYPE_KEYBOARD_ONLY, self:getControllerType() == GameSettingsModel.CONTROLLER_TYPE_KEYBOARD_ONLY)  elseif bindingName == BND_IS_CONTROLLER_TYPE_KEYBOARD_AND_MOUSE then    self.im.Publish(BND_IS_CONTROLLER_TYPE_KEYBOARD_AND_MOUSE, self:getControllerType() == GameSettingsModel.CONTROLLER_TYPE_KEYBOARD_AND_MOUSE)  endendfunction GameSettingsModel:_publishControllerConfigurationFlag(bindingName)  if bindingName == nil then    self:_publishControllerConfigurationFlag(BND_IS_CONTROLLER_CONFIGURATION_CLASSIC)    self:_publishControllerConfigurationFlag(BND_IS_CONTROLLER_CONFIGURATION_ALTERNATE)  elseif bindingName == BND_IS_CONTROLLER_CONFIGURATION_CLASSIC then    self.im.Publish(BND_IS_CONTROLLER_CONFIGURATION_CLASSIC, self:getControllerConfiguration() == GameSettingsModel.CONTROLLER_CONFIGURATION_CLASSIC)  elseif bindingName == BND_IS_CONTROLLER_CONFIGURATION_ALTERNATE then    self.im.Publish(BND_IS_CONTROLLER_CONFIGURATION_ALTERNATE, self:getControllerConfiguration() == GameSettingsModel.CONTROLLER_CONFIGURATION_ALTERNATE)  elseif bindingName == BND_IS_CONTROLLER_CONFIGURATION_TWO_BUTTONS then    self.im.Publish(BND_IS_CONTROLLER_CONFIGURATION_TWO_BUTTONS, self:getControllerConfiguration() == GameSettingsModel.CONTROLLER_CONFIGURATION_TWO_BUTTONS)  endendfunction GameSettingsModel:finalize()  self.im.Unsubscribe(BND_IS_CONTROLLER_TYPE_GAMEPAD)  self.im.Unsubscribe(BND_IS_CONTROLLER_TYPE_KEYBOARD_ONLY)  self.im.Unsubscribe(BND_IS_CONTROLLER_TYPE_KEYBOARD_AND_MOUSE)  self.im.Unsubscribe(BND_IS_CONTROLLER_CONFIGURATION_CLASSIC)  self.im.Unsubscribe(BND_IS_CONTROLLER_CONFIGURATION_ALTERNATE)  self.im.Unsubscribe(BND_IS_CONTROLLER_CONFIGURATION_TWO_BUTTONS)endreturn GameSettingsModel